component.script:
"""LLM Request: one call to a model in the platform's model catalogue.

The managed provider is a platform-run Azure AI Foundry deployment reached
through ``perceivo.managed_service.ai``, authenticated server-side, so nothing
is bound on the node. Every other provider is called directly with the
organization's own key, read by NAME from the ``api_key`` secret.

The component records no cost itself. A managed call is booked by the AI
Foundry proxy from Azure's own token counts, including a call that returns no
text; an own-key call is billed by the platform from the tokens_in, tokens_out,
provider and model in this component's response_data. A cost.record here would
book the same tokens a second time.
"""

import json
import re

import httpx
import perceivo

_PROVIDERS = ("managed", "anthropic", "openai", "google")
_REASONING_EFFORTS = ("low", "medium", "high")
_DEFAULT_MODEL = "gpt-5.2"
_DEFAULT_SYSTEM_PROMPT = "You are a helpful assistant."
_DEFAULT_USER_PROMPT = "${prompt}"
_TIMEOUT_SECONDS = 120.0

# Bring-your-own-key endpoints. The managed provider never uses these.
_ANTHROPIC_URL = "https://api.anthropic.com/v1/messages"
_OPENAI_URL = "https://api.openai.com/v1/chat/completions"
_GOOGLE_URL = "https://generativelanguage.googleapis.com/v1beta/models/{model}:generateContent"

# ${field} or ${nested.field}, filled from the inbound request_data.
_PLACEHOLDER = re.compile(r"\$\{([\w.]+)\}")
_ABSENT = object()


def _lookup(data, path: str):
    """The value at a dotted path inside nested dicts, or _ABSENT."""
    value = data
    for part in path.split("."):
        if not isinstance(value, dict) or part not in value:
            return _ABSENT
        value = value[part]
    return value


def _as_text(value) -> str:
    return value if isinstance(value, str) else json.dumps(value, default=str)


def _fill(template: str, data: dict) -> str:
    """Replace each ${path} found in data; leave unknown placeholders as written."""

    def _replace(match):
        value = _lookup(data, match.group(1))
        return match.group(0) if value is _ABSENT else _as_text(value)

    return _PLACEHOLDER.sub(_replace, template)


def _text_param(name: str, default: str) -> str:
    value = perceivo.params.get(name, default)
    return default if value is None else str(value)


def _number_param(name: str, label: str, default, low, high, integer: bool = False):
    """A numeric node parameter, checked against the range the Inspector offers."""
    raw = perceivo.params.get(name, default)
    if raw is None or raw == "":
        raw = default
    try:
        value = float(raw)
    except (TypeError, ValueError):
        raise ValueError(f"{label} is {raw!r}; it must be a number.") from None
    if integer:
        if not value.is_integer():
            raise ValueError(f"{label} is {raw!r}; it must be a whole number.")
        value = int(value)
    if not low <= value <= high:
        raise ValueError(f"{label} is {raw!r}; it must be between {low} and {high}.")
    return value


def _user_message(artifact_data, request_data: dict) -> str:
    """The User Prompt with its placeholders filled, or the inbound data itself.

    When the prompt is blank, or names a field the inbound data does not carry,
    the inbound artifact is sent instead, then the whole request_data as JSON.
    """
    prompt = _fill(_text_param("user_prompt", _DEFAULT_USER_PROMPT), request_data).strip()
    if prompt and not _PLACEHOLDER.search(prompt):
        return prompt
    if artifact_data not in (None, "", {}, []):
        return _as_text(artifact_data)
    if request_data:
        return json.dumps(request_data, default=str)
    raise ValueError(
        "There is nothing to send to the model: the User Prompt is empty or names "
        "a field the incoming data does not carry, and no data arrived at the node. "
        f"Fields received: {sorted(request_data)}."
    )


def _anthropic_rejects_sampling(model: str) -> bool:
    """True for Anthropic models that refuse temperature (Opus 4.7+, Sonnet 5+, Fable, Mythos).

    Opus 4.6 and earlier, Sonnet 4.x, Haiku and the legacy claude-3 ids still
    accept it. Detected by name so a new model of the same family is covered.
    """
    name = model.lower().strip()
    if "fable" in name or "mythos" in name:
        return True
    match = re.search(r"(?:^|claude-)(opus|sonnet|haiku)-(\d+)(?:-(\d{1,2})(?!\d))?", name)
    if not match:
        return False
    family, major = match.group(1), int(match.group(2))
    minor = int(match.group(3)) if match.group(3) else 0
    if family == "opus":
        return (major, minor) >= (4, 7)
    if family == "sonnet":
        return major >= 5
    return False


def _openai_is_reasoning(model: str) -> bool:
    """o-series and the non-chat gpt-5 family take max_completion_tokens and no temperature."""
    name = model.lower().strip()
    return bool(re.match(r"o\d", name)) or (name.startswith("gpt-5") and "chat" not in name)


def _provider_error(provider: str, response: httpx.Response, api_key: str) -> RuntimeError:
    """A failed provider call as an error naming the status and the provider's message.

    Only the provider's own error message is kept, never the raw body, and the
    key is masked in case the provider echoed it back.
    """
    try:
        body = response.json()
    except ValueError:
        body = None
    message = ""
    if isinstance(body, dict):
        error = body.get("error")
        if isinstance(error, dict):
            message = str(error.get("message") or "")
        elif isinstance(error, str):
            message = error
    message = message or response.reason_phrase or ""
    if api_key:
        message = message.replace(api_key, "***")
    message = message[:300]
    return RuntimeError(f"{provider} API error {response.status_code}: {message}")


async def _post(provider: str, url: str, headers: dict, body: dict, api_key: str) -> dict:
    """POST a JSON body. Redirects are not followed; a non-200 status raises."""
    async with httpx.AsyncClient(timeout=_TIMEOUT_SECONDS) as client:
        response = await client.post(url, headers=headers, json=body)
    if response.status_code != 200:
        raise _provider_error(provider, response, api_key)
    return response.json()


async def _call_managed(
    model, system_prompt, user_message, temperature, max_tokens, reasoning_effort
):
    options = {"temperature": temperature, "max_tokens": max_tokens}
    if reasoning_effort:
        options["reasoning_effort"] = reasoning_effort
    response = await perceivo.managed_service.ai.invoke(
        perceivo.types.AIService.CHAT,
        model=model,
        messages=[{"role": "user", "content": user_message}],
        system_prompt=system_prompt,
        **options,
    )
    choice = (response.get("choices") or [{}])[0] or {}
    usage = response.get("usage") or {}
    return {
        "text": (choice.get("message") or {}).get("content") or "",
        "finish_reason": choice.get("finish_reason") or "",
        # Current SDKs add tokens_in/tokens_out; an older runtime leaves only the
        # provider's usage block, so it is read when they are absent.
        "tokens_in": int(response.get("tokens_in") or usage.get("prompt_tokens") or 0),
        "tokens_out": int(response.get("tokens_out") or usage.get("completion_tokens") or 0),
    }


async def _call_anthropic(api_key, model, system_prompt, user_message, temperature, max_tokens):
    body = {
        "model": model,
        "max_tokens": max_tokens,
        "system": system_prompt,
        "messages": [{"role": "user", "content": user_message}],
    }
    if not _anthropic_rejects_sampling(model):
        body["temperature"] = temperature
    headers = {"x-api-key": api_key, "anthropic-version": "2023-06-01"}
    result = await _post("anthropic", _ANTHROPIC_URL, headers, body, api_key)
    usage = result.get("usage") or {}
    blocks = result.get("content") or []
    return {
        # Only text blocks are the answer; thinking and tool blocks are not.
        "text": "".join(
            b.get("text") or "" for b in blocks if isinstance(b, dict) and b.get("type") == "text"
        ),
        "finish_reason": result.get("stop_reason") or "",
        "tokens_in": int(usage.get("input_tokens") or 0),
        "tokens_out": int(usage.get("output_tokens") or 0),
    }


async def _call_openai(api_key, model, system_prompt, user_message, temperature, max_tokens):
    body = {
        "model": model,
        "messages": [
            {"role": "system", "content": system_prompt},
            {"role": "user", "content": user_message},
        ],
    }
    if _openai_is_reasoning(model):
        body["max_completion_tokens"] = max_tokens
    else:
        body["max_tokens"] = max_tokens
        body["temperature"] = temperature
    headers = {"Authorization": f"Bearer {api_key}"}
    result = await _post("openai", _OPENAI_URL, headers, body, api_key)
    usage = result.get("usage") or {}
    choice = (result.get("choices") or [{}])[0] or {}
    return {
        "text": (choice.get("message") or {}).get("content") or "",
        "finish_reason": choice.get("finish_reason") or "",
        "tokens_in": int(usage.get("prompt_tokens") or 0),
        "tokens_out": int(usage.get("completion_tokens") or 0),
    }


async def _call_google(api_key, model, system_prompt, user_message, temperature, max_tokens):
    body = {
        "contents": [{"role": "user", "parts": [{"text": user_message}]}],
        "systemInstruction": {"parts": [{"text": system_prompt}]},
        "generationConfig": {"temperature": temperature, "maxOutputTokens": max_tokens},
    }
    # The key travels in a header, never in the URL, so it cannot reach a log line.
    headers = {"x-goog-api-key": api_key}
    result = await _post("google", _GOOGLE_URL.format(model=model), headers, body, api_key)
    usage = result.get("usageMetadata") or {}
    candidate = (result.get("candidates") or [{}])[0] or {}
    parts = (candidate.get("content") or {}).get("parts") or []
    finish_reason = candidate.get("finishReason") or ""
    if not candidate:
        # A prompt blocked before generation carries no candidate at all.
        finish_reason = str((result.get("promptFeedback") or {}).get("blockReason") or "")
    return {
        "text": "".join(p.get("text") or "" for p in parts if isinstance(p, dict)),
        "finish_reason": finish_reason,
        "tokens_in": int(usage.get("promptTokenCount") or 0),
        "tokens_out": int(usage.get("candidatesTokenCount") or 0),
    }


def _preview(text: str, limit: int) -> str:
    flat = " ".join(text.split())
    return flat if len(flat) <= limit else flat[:limit] + "..."


@perceivo.agent
async def llm_request(input: perceivo.primitives.AgentInput) -> perceivo.primitives.AgentOutput:
    """Send one prompt to the configured provider and model and return the reply.

    Provider, model, prompts and sampling settings are node parameters. ${field}
    placeholders in either prompt are filled from the inbound request_data.

    A misconfigured node raises ValueError before any call is made. A failed
    call raises and is not caught, and a reply with no text raises RuntimeError:
    the run fails rather than passing an empty answer downstream.
    """
    request_data = input.request_data or {}

    provider = _text_param("provider", "managed").strip().lower() or "managed"
    if provider not in _PROVIDERS:
        raise ValueError(f"LLM Provider is {provider!r}. Choose one of: {', '.join(_PROVIDERS)}.")
    # The Inspector labels each model with its price, e.g. "gpt-5.2 ($2/$8 per 1M)".
    model = _text_param("model", _DEFAULT_MODEL).split(" (")[0].strip()
    if not model:
        raise ValueError("Model is empty. Choose a model for the selected provider.")
    temperature = _number_param("temperature", "Temperature", 0.7, 0, 2)
    max_tokens = _number_param("max_tokens", "Max Tokens", 4000, 100, 100_000, integer=True)
    reasoning_effort = _text_param("reasoning_effort", "").strip().lower()
    if reasoning_effort and reasoning_effort not in _REASONING_EFFORTS:
        raise ValueError(
            f"Reasoning Effort is {reasoning_effort!r}. Choose one of: "
            f"{', '.join(_REASONING_EFFORTS)}, or leave it blank."
        )
    if reasoning_effort and provider != "managed":
        raise ValueError(
            f"Reasoning Effort applies to the managed provider only; clear it for {provider}."
        )
    system_prompt = (
        _fill(_text_param("system_prompt", _DEFAULT_SYSTEM_PROMPT), request_data).strip()
        or _DEFAULT_SYSTEM_PROMPT
    )
    artifact_data = input.artifact.data if input.artifact is not None else None
    user_message = _user_message(artifact_data, request_data)

    api_key = ""
    if provider != "managed":
        api_key = await perceivo.secrets.get("api_key", None)
        if not api_key:
            raise ValueError(
                f"LLM Provider is {provider} but no api_key secret is bound. Bind the "
                "organization's key in the Inspector, or choose the managed provider."
            )

    perceivo.log.info(
        "Calling LLM",
        provider=provider,
        model=model,
        temperature=temperature,
        max_tokens=max_tokens,
        reasoning_effort=reasoning_effort or None,
        prompt_chars=len(user_message),
    )
    if provider == "managed":
        result = await _call_managed(
            model, system_prompt, user_message, temperature, max_tokens, reasoning_effort
        )
    else:
        call = {"anthropic": _call_anthropic, "openai": _call_openai, "google": _call_google}
        result = await call[provider](
            api_key, model, system_prompt, user_message, temperature, max_tokens
        )

    reply = result["text"]
    tokens_in, tokens_out = result["tokens_in"], result["tokens_out"]

    if not reply.strip():
        raise RuntimeError(
            f"{provider}/{model} returned no text (finish_reason="
            f"{result['finish_reason'] or 'unset'}, completion_tokens={tokens_out}, "
            f"max_tokens={max_tokens}). A reasoning model can spend the whole budget before "
            "answering: raise Max Tokens or lower Reasoning Effort."
        )

    summary = (
        f"[LLM via {provider}/{model}] Role: {_preview(system_prompt, 150)} | "
        f"Processed {len(user_message)} chars of input. "
        f"Response ({len(reply)} chars): {_preview(reply, 200)}"
    )
    perceivo.log.info(
        "LLM replied",
        provider=provider,
        model=model,
        reply_chars=len(reply),
        tokens_in=tokens_in,
        tokens_out=tokens_out,
    )

    response_data = {
        "response": reply,
        "tokens_in": tokens_in,
        "tokens_out": tokens_out,
        "model": model,
        "provider": provider,
        "conversation_log": summary,
    }
    return perceivo.primitives.AgentOutput(
        artifact=perceivo.primitives.Artifact(
            type=perceivo.primitives.ArtifactType.JSON,
            data=dict(response_data),
            mime_type="application/json",
        ),
        response_data=response_data,
    )
